/* Buildless, offline developer tool. No data leaves this browser. */
(() => {
  'use strict';
  const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone=v=>JSON.parse(JSON.stringify(v));
  const original=window.BESIEGED_DATA, G=window.EventGraph;
  const storageKey='besieged-event-map-v1:'+original.repositoryCommit+':'+original.revision+':'+original.sources.map(s=>s.sha256.slice(0,12)).join('');
  let data=clone(original), collection=original.preparation?'proposal':'runtime', selected=original.preparation?'proposal:story0':'runtime:story18', view='map';
  let history=[],future=[], analysis, filtered=[], drawn=[], drawnEdges=[], positions={}, zoom=1, pan={x:0,y:0};
  let editorMode='',editorId='',editorChoice='', editNew=false, timer, drag=null, checkType='', sourceQuery='';
  let persistenceError='',stored=false;
  try {const saved=localStorage.getItem(storageKey);if(saved){const candidate=JSON.parse(saved);const errors=G.validate(candidate);if(errors.length)throw new Error(errors.join(' '));data=candidate;stored=true;}}catch(e){persistenceError='Saved workspace could not be loaded: '+e.message;}
  try {const plan=JSON.parse(localStorage.getItem(storageKey+':preparation')||'null');if(plan&&typeof plan.bookings==='object'&&!Array.isArray(plan.bookings)){data.preparationPreview=plan;stored=true;}}catch{}
  const collectionText={proposal:'Implemented calendar · selectable preparations · siege event chains',runtime:'Yarn selected by Continue Game · local working copy',design:'Imported narrative drafts · paragraph-level evidence',catalogue:'Earlier spreadsheet generation · ID mappings unverified'};
  const collectionNote={proposal:'Current Unity source. Coloured cards separate dates, slots and selectable events. Editing this map does not edit the game.',runtime:'Full Unity source audit, including utility and unscheduled nodes. Use Current Unity flow for the readable campaign.',design:'Source labels report writing status. Prose choices carry review flags.',catalogue:'Workbook IDs are preserved. No automatic crosswalk to story/random IDs.'};
  function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,5000);}
  function persist(){
    let planSaved=false;
    try {localStorage.setItem(storageKey+':preparation',JSON.stringify(data.preparationPreview||null));planSaved=!!data.preparationPreview;}catch{}
    try{localStorage.setItem(storageKey,JSON.stringify(data));$('#save-state').textContent='Saved in this browser';$('#save-state').style.color='var(--teal)';return true;}
    catch(e){$('#save-state').textContent=planSaved?'Preparation plan saved · export event edits':'Export to keep changes';$('#save-state').style.color='var(--gold)';toast('Browser storage is full or unavailable. Export JSON to preserve all event edits.');return false;}
  }
  function commit(fn){history.push(clone(data));if(history.length>35)history.shift();future=[];fn();data.modifiedAt=new Date().toISOString();persist();render();}
  function undo(){if(!history.length)return;future.push(clone(data));data=history.pop();persist();render();toast('Undone');}
  function redo(){if(!future.length)return;history.push(clone(data));data=future.pop();persist();render();toast('Redone');}
  function node(id){return data.events.find(n=>n.id===id);}
  function source(n){return data.sources.find(s=>s.id===n.sourceId);}
  function nodeName(id){const n=node(id);return n? n.title:'Missing target: '+id;}
  function categoryOptions(){const list=data.events.filter(n=>n.collection===collection);for(const [sel,key,label]of [['#category','category','All categories'],['#status','status','All statuses']]){const current=$(sel).value;$(sel).innerHTML=`<option value="">${label}</option>`+[...new Set(list.map(n=>n[key]))].sort().map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');if([...$(sel).options].some(o=>o.value===current))$(sel).value=current;}}
  function matches(n){const query=$('#search').value.trim().toLowerCase(),cat=$('#category').value,status=$('#status').value,origin=$('#origin').value,health=$('#health-filter').value;const section=$('#flow-section').value;const inSection=collection!=='proposal'||view!=='map'||(section==='preparation'?['calendar','pool'].includes(n.section):n.section===section);return inSection&&(!cat||n.category===cat)&&(!status||n.status===status)&&(!origin||n.origin===origin)&&(!query||JSON.stringify(n).toLowerCase().includes(query))&&(!health||analysis.findings.some(f=>f.node===n.id&&(f.severity===health||f.type===health)));}
  function edgesForView(){let edges=analysis.links.filter(e=>(e.kind!=='jump'||$('#show-jumps').checked)&&(e.kind!=='schedule'||$('#show-schedule').checked)&&(!['influence','availability'].includes(e.relation)||$('#show-potential').checked));if($('#show-state').checked)edges=edges.concat(G.correlations(analysis.nodes,selected));return edges;}
  function updateScope(edges){let allowed=null;const scope=$('#scope').value;
    if(scope==='down')allowed=G.walk(selected,edges);if(scope==='up')allowed=G.walk(selected,edges,'up');
    if(scope==='near'){allowed=new Set([selected]);for(const e of edges)if(e.source===selected||e.target===selected){allowed.add(e.source);allowed.add(e.target);}}
    return filtered.filter(n=>!allowed||allowed.has(n.id));
  }
  function render(){
    document.body.classList.toggle('conversation-mode',view==='conversations');
    if(!node(selected)||node(selected).collection!==collection)selected=data.events.find(n=>n.collection===collection)?.id||'';
    analysis=G.analyze(data,collection);filtered=analysis.nodes.filter(matches);
    $('#collection-note').textContent=collectionNote[collection];$('#dataset-caption').textContent=collectionText[collection];
    $('#metrics').innerHTML=`<div><strong>${analysis.counts.events}</strong><span>Events</span></div><div><strong>${analysis.counts.choices}</strong><span>Choices</span></div><div><strong>${analysis.counts.links}</strong><span>Links</span></div>`;
    $('#library-count').textContent=`${filtered.length} / ${analysis.counts.events} events`;
    $('#check-badge').textContent=analysis.counts.errors+analysis.counts.review;
    $('#event-list').innerHTML=filtered.map(n=>{const errs=analysis.findings.filter(f=>f.node===n.id&&f.severity==='error').length;return`<button class="event-row ${n.id===selected?'selected':''}" data-select="${esc(n.id)}" role="listitem"><span class="event-code">${esc(n.code)}<span>${errs?'⚠ '+errs:n.entry?'ENTRY':n.isChain?'CHAIN':''}</span></span><strong>${esc(n.title)}</strong><span class="sub"><span class="dot ${esc(n.origin)}"></span>${esc(n.flowRole==='slot'?'Choose from the pool →':n.flowRole==='fixed'?n.timing:n.category)}${n.choices.length?' · '+n.choices.length+' choices':''}${n.edited?' · edited':''}</span></button>`;}).join('')||'<p class="muted small">No matching events. Clear filters to see the full collection.</p>';
    $('#undo').disabled=!history.length;$('#redo').disabled=!future.length;
    $$('.view-bar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
    for(const v of ['map','table','checks','sources','plan','diplomacy','conversations'])$('#'+v+'-view').hidden=v!==view;
    $('#map-options').hidden=view!=='map';
    $('#flow-section').hidden=collection!=='proposal';if(view==='map')renderGraph();if(view==='table')renderTable();if(view==='checks')renderChecks();if(view==='sources')renderSources();if(view==='plan')renderPlan();if(view==='diplomacy')renderDiplomacy();
    renderInspector();
  }
  function select(id,locate=false){const n=node(id);if(!n){toast('This target is missing. Select its incoming arrow to edit the reference.');return;}if(n.collection!==collection){collection=n.collection;$('#collection').value=collection;if(view==='plan'&&collection!=='proposal')view='map';categoryOptions();}selected=id;if(view==='map'&&n.section)$('#flow-section').value=['calendar','pool'].includes(n.section)?'preparation':n.section;render();$('#inspector').scrollTop=0;if(locate&&view==='map')focusNode();}
  function splitTitle(text,max=33,lines=2){const words=text.split(/\s+/),out=[];let s='';for(const w of words){if((s+' '+w).trim().length>max&&s){out.push(s);s=w;}else s+=(s?' ':'')+w;}if(s)out.push(s);if(out.length>lines){out.length=lines;out[lines-1]=out[lines-1].slice(0,max-1)+'…';}return out;}
  function renderGraph(){
    let edges=edgesForView();drawn=updateScope(edges);let ids=new Set(drawn.map(n=>n.id));
    drawnEdges=edges.filter(e=>ids.has(e.source)&&(ids.has(e.target)||!node(e.target)));
    const missing=[...new Set(drawnEdges.filter(e=>!node(e.target)).map(e=>e.target))].map(id=>({id,code:id.split(':').pop(),title:'Missing jump target',category:'missing',origin:'diagnostic',missing:true,choices:[]}));
    drawn=drawn.concat(missing);positions=G.layout(drawn,drawnEdges);if(collection==='proposal'&&$('#scope').value==='near'){const incoming=drawn.filter(n=>n.id!==selected&&drawnEdges.some(e=>e.source===n.id&&e.target===selected)),outgoing=drawn.filter(n=>n.id!==selected&&!incoming.includes(n));positions[selected]={x:420,y:Math.max(incoming.length,outgoing.length)*70};incoming.forEach((n,i)=>positions[n.id]={x:40,y:40+i*145});outgoing.forEach((n,i)=>positions[n.id]={x:800,y:40+i*145});for(const n of drawn)if(n.userPosition)positions[n.id]=n.userPosition;}$('#map-empty').hidden=!!drawn.length;
    const edgeHTML=drawnEdges.map(e=>{const a=positions[e.source],b=positions[e.target];if(!a||!b)return'';let x1=a.x+278,y1=a.y+57,x2=b.x,y2=b.y+57;const dx=Math.max(75,Math.abs(x2-x1)*.5);const d=e.kind==='schedule'?`M${a.x+139} ${a.y+118} L${b.x+139} ${b.y}`:e.source===e.target?`M${a.x+278} ${a.y+40} C${a.x+370} ${a.y-75},${a.x-75} ${a.y-75},${a.x} ${a.y+40}`:`M${x1} ${y1} C${x1+dx} ${y1},${x2-dx} ${y2},${x2} ${y2}`;
      const pairIndex=drawnEdges.filter(x=>x.source===e.source&&x.target===e.target).findIndex(x=>x.id===e.id);const text=e.kind==='manual'?e.label.slice(0,42):e.kind==='schedule'?'next turn':e.kind==='state'?e.label:e.conditions.length?e.conditions.join(' · ').slice(0,34):e.choiceId?'choice →':'continue';
      return`<g class="edge ${esc(e.kind)} ${esc(e.relation||'')}" data-edge="${esc(e.id)}" tabindex="0" role="button" aria-label="${esc(e.kind+': '+nodeName(e.source)+' to '+nodeName(e.target))}"><title>${esc(e.kind+' · '+e.label+'\n'+e.conditions.join('\n')+'\n'+e.note)}</title><path d="${d}"/><path class="edge-hit" d="${d}"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-10-pairIndex*18}" text-anchor="middle">${esc(text)}</text></g>`;
    }).join('');
    const nodesHTML=drawn.map(n=>{const p=positions[n.id],title=splitTitle(n.title),errors=analysis.findings.some(f=>f.node===n.id&&f.severity==='error');return`<g class="node role-${esc(n.flowRole||'source')} ${n.id===selected?'selected':''} ${n.missing?'missing':''}" transform="translate(${p.x},${p.y})" data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.code+': '+n.title)}"><title>${esc(n.title+'\n'+n.id)}</title><rect width="278" height="118" rx="7"/><rect class="accent" width="3" height="32" x="0" y="14" rx="1"/><text class="code" x="16" y="25">${esc(n.code)}${errors?'  ⚠':''}</text><text class="meta" x="261" y="24" text-anchor="end">${n.missing?'UNRESOLVED':n.edited?'EDITED':n.origin==='sample'?'SAMPLE':n.collection==='proposal'?(n.flowRole==='slot'?'CHOOSE ONE':n.flowRole==='fixed'?'FIXED DATE':n.flowRole==='unlocked'?'UNLOCKABLE':n.flowRole==='selectable'?'SELECTABLE':n.isChain?'CHAIN':'STANDALONE'):n.origin==='authored'?'AUTHORED':'IMPORTED'}</text>${title.map((t,i)=>`<text class="title" x="16" y="${49+i*18}">${esc(t)}</text>`).join('')}<line x1="16" y1="85" x2="261" y2="85" stroke="#3a444b"/><text class="meta" x="16" y="104">${esc(n.flowRole==='slot'?'Choose from the pool →':n.flowRole==='fixed'?n.timing:n.category)}${n.choices.length?' · '+n.choices.length+' choices':''}</text><text class="meta" x="261" y="104" text-anchor="end">${n.missing?'REFERENCE ONLY':n.review?.length?'REVIEW':''}</text></g>`;}).join('');
    const section=$('#flow-section').value;
    const headings=collection==='proposal'&&$('#scope').value==='all'?(section==='preparation'?'<text class="section-label" x="55" y="35">CALENDAR</text><text class="section-label" x="470" y="35">SELECTABLE POOL · CHOOSE ONE PER SLOT</text><text class="section-note" x="470" y="970">Choice follow-ups · shown only when that choice is taken</text>':''):'';
    $('#world').innerHTML=headings+edgeHTML+nodesHTML;transform();
  }
  const rehearsal=()=>({...PreparationRules.fresh(),...(data.preparationPreview||{})});
  let councilMonth='', councilQuery='', councilLane='';
  function openCouncil(month){councilMonth=month;councilQuery='';councilLane='';renderCouncil();$('#council-menu').showModal();}
  function renderCouncil(){
    const p=data.preparation,s=rehearsal(),booking=s.bookings[councilMonth];
    const shown=p.projectPool.filter(k=>{const e=node('proposal:'+k);return (!councilQuery||[e.title,e.description,...e.choices.map(c=>c.label)].join(' ').toLowerCase().includes(councilQuery.toLowerCase()))&&(!councilLane||e.category===councilLane);});
    $('#council-menu').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">MONTHLY COUNCIL · DEVELOPER REHEARSAL</span><h2>${esc(councilMonth)}</h2></div><button id="close-council" aria-label="Close preparation menu">×</button></div><p>One month. One preparation. Inspect the choices before committing a slot. This plans your route; it does not execute resources or a Unity event.</p><div class="council-settings"><label>Persistent achievements<input id="career-count" type="number" min="0" max="999" value="${s.achievementCount}"></label><label><input id="career-suggestions" type="checkbox" ${s.useSuggestedThresholds?'checked':''}> Use current playtest counts: grain 1 · Rumeli 2 · Greek Fire 3 · scorched earth 2</label></div><div class="council-search"><input id="council-search" type="search" aria-label="Search preparation options" placeholder="Find a preparation…" value="${esc(councilQuery)}"><select id="council-lane" aria-label="Preparation topic"><option value="">All topics</option>${[...new Set(p.projectPool.map(k=>node('proposal:'+k).category))].map(l=>`<option ${l===councilLane?'selected':''}>${esc(l)}</option>`).join('')}</select></div>${booking?`<div class="council-booking">This month: <b>${booking==='pass'?'Passed':esc(node('proposal:'+booking)?.title||booking)}</b><button id="release-month">Release this slot</button></div>`:'<p class="small muted">Locked career options remain visible. Their current playtest thresholds are shown on each card.</p>'}<div class="council-grid">${shown.map(k=>{const e=node('proposal:'+k),a=PreparationRules.availability(p,k,councilMonth,s),draft=e.status==='New creative draft';return `<article class="council-option ${a.available?'':'locked'}"><span class="tag ${draft?'gold':'teal'}">${draft?'NEW CREATIVE DRAFT':e.access.kind==='base'?'BASE OPTION':'CAREER UNLOCK'}</span><h3>${esc(e.title.replace(/^Siege Preparation [—-] /,''))}</h3><p>${esc((e.description||e.notes.split('\n')[0]).length>300?(e.description||e.notes.split('\n')[0]).slice(0,280)+'…':(e.description||e.notes.split('\n')[0]))}</p><details><summary>${e.choices.length} choices and outcomes</summary>${e.choices.map(c=>`<p><b>${esc(c.label.replace(/#focus:\d+/g,''))}</b><br>${esc(c.extraction==='authored'?c.text:c.effects.map(f=>f.command).join('; ')||'Inspect the source narrative for details.')}${c.conditions.length?'<br><em>'+esc(c.conditions.join(' · '))+'</em>':''}</p>`).join('')}</details><p class="council-reason">${a.available?'Available · one monthly slot':esc(a.reasons.join(' · '))}</p><div><button data-council-inspect="${esc(k)}">Inspect in map</button><button data-council-pick="${esc(k)}" ${a.available?'':'disabled'} class="gold">Choose ${esc(e.title.replace(/^Siege Preparation [—-] /,''))}</button></div></article>`;}).join('')||'<p>No preparation matches this search.</p>'}</div><div class="dialog-actions"><button id="pass-month" ${booking?'disabled':''}>Pass this month</button><span class="small muted">Selections travel with Export JSON. Release a slot to revise your plan.</span></div>`;
    $('#close-council').onclick=()=>$('#council-menu').close();
    $('#council-search').oninput=e=>{councilQuery=e.target.value;const pos=e.target.selectionStart;renderCouncil();$('#council-search').focus();$('#council-search').setSelectionRange(pos,pos);};
    $('#council-lane').onchange=e=>{councilLane=e.target.value;renderCouncil();};
    $('#career-count').oninput=e=>{const v=Math.min(999,Math.max(0,Math.floor(Number(e.target.value)||0)));commit(()=>data.preparationPreview={...rehearsal(),achievementCount:v});renderCouncil();$('#career-count').focus();};
    $('#career-suggestions').closest('label').hidden=true;$('#career-suggestions').onchange=e=>{const v=e.target.checked;commit(()=>data.preparationPreview={...rehearsal(),useSuggestedThresholds:v});renderCouncil();};
    if($('#release-month'))$('#release-month').onclick=()=>{commit(()=>{const s=rehearsal();delete s.bookings[councilMonth];data.preparationPreview=s;});renderCouncil();};
    const pick=k=>{try{const next=PreparationRules.commit(p,rehearsal(),k,councilMonth);commit(()=>data.preparationPreview=next);renderCouncil();toast('Preparation slot reserved in the developer plan');}catch(e){toast(e.message);}};
    $$('#council-menu [data-council-pick]').forEach(b=>b.onclick=()=>pick(b.dataset.councilPick));
    $('#pass-month').onclick=()=>pick('pass');
    $$('#council-menu [data-council-inspect]').forEach(b=>b.onclick=()=>{$('#council-menu').close();selected='proposal:'+b.dataset.councilInspect;collection='proposal';view='map';$('#collection').value=collection;$('#scope').value='near';categoryOptions();render();fit();});
  }
  function renderPlan(){
    const p=data.preparation,s=rehearsal();
    const card=k=>{const n=node('proposal:'+k);return n?`<button class="plan-event role-${esc(n.flowRole)}" data-select="${esc(n.id)}"><b>${esc(n.title)}</b><small>${n.choices.length} choices${n.review.length?' · needs review':''}</small></button>`:'';};
    $('#plan-view').innerHTML=`<div class="plan-intro"><span class="tag teal">CURRENT UNITY CALENDAR</span><h2>Read the campaign one event at a time.</h2><p>Fixed events keep their dates. In each of nine flexible months, choose one unused preparation from the 15-event pool. Four options require career achievements.</p><button data-view="map" class="gold">Open dependency map →</button></div><div class="plan-months">${p.months.map(m=>`<article class="plan-month ${m.type.startsWith('Flexible')?'flexible':'fixed'}"><h3>${esc(m.date)}<small>${esc(m.type)}</small></h3><div>${m.type.startsWith('Flexible')?`<button class="month-council" data-council="${esc(m.date)}"><b>${s.bookings[m.date]?(s.bookings[m.date]==='pass'?'Month passed':esc(node('proposal:'+s.bookings[m.date])?.title)):'Choose one preparation'}</b><small>Inspect the available choices →</small></button>`:m.events.map(card).join('')}</div></article>`).join('')}</div><div class="plan-intro"><h2>Selectable preparation pool</h2><p>Choose from this pool during flexible months; each preparation can be used once.</p>${p.baseProjectPool.map(card).join('')}<h2>Career unlocks</h2>${p.unlockedProjectPool.map(card).join('')}<details><summary>Playtest decisions still open</summary>${p.decisions.map(q=>`<p><b>${esc(q.question)}</b><br>${esc(q.recommendation)}</p>`).join('')}</details></div>`;
    $$('#plan-view [data-council]').forEach(b=>b.onclick=()=>openCouncil(b.dataset.council));
  }
  let galataPanelOpen=false;
  function renderDiplomacy(){
    const p=data.preparation?.politics;if(!p){$('#diplomacy-view').innerHTML='<p>No political design in this workspace.</p>';return;}
    const s=rehearsal(),current=p.states.find(x=>x.id===s.galataState)||p.states[0],a=PreparationRules.attackEligibility(data.preparation,s);
    $('#diplomacy-view').innerHTML=`<div class="plan-intro"><span class="tag gold">DIPLOMACY DESIGN PREVIEW · NOT LIVE GAME STATE</span><h2>Diplomacy & Court</h2><p>Character loyalty belongs to each person. It is separate from army support, troop morale and Galata goodwill.</p><article class="plan-month"><h3>Giovanni’s loyalty</h3><div><b>Post-war promise +15 · Immediate autonomous grant +30</b><p>Starting loyalty: undecided. Immediate grant also increases Galata defences; amount TBD. A post-war promise keeps imperial control until victory fulfils it.</p></div></article><button id="open-galata-panel" class="plan-event"><b>Galata · relations and political status</b><small>Diplomatic options, defences and Ottoman attack eligibility</small></button>${galataPanelOpen?`<label for="galata-preview-state">Preview political state</label><select id="galata-preview-state">${p.states.map(x=>`<option value="${esc(x.id)}" ${x.id===s.galataState?'selected':''}>${esc(x.label)}</option>`).join('')}</select><h3>${esc(current.label)}</h3><p>${esc(current.description)}</p><p class="small muted">Goodwill and defence values await balancing. No fixed Galata treasury or troop inventory is assumed. Changing this preview is not a capture and does not open governance.</p><h3>Diplomatic options with Galata</h3><div class="political-actions">${p.actions.filter(x=>x.states.includes(s.galataState)).map(x=>`<button class="plan-event" data-political-action="${esc(x.id)}">${esc(x.title)}</button>`).join('')}</div><p id="political-action-detail" class="review-note">Choose an action to inspect its terms.</p><h3>Ottoman special action: Attack Galata</h3><div class="council-settings"><label><input id="preview-siege" type="checkbox" ${s.siegeActive?'checked':''}> Siege active</label><label>Land-operation delay remaining<input id="preview-delay" type="number" min="0" max="99" value="${s.landDelayDays}"></label></div><p id="attack-eligibility" class="attack-state ${a.available?'available':''}">${a.available?'AVAILABLE — Ottoman forces may target Galata’s defences.':esc(a.reasons.join(' · '))}</p><button id="inspect-galata-attack">Inspect attack event</button><p>Eligibility is working in this preview. Attack costs, damage and conquest rules remain undecided. The action becomes unavailable if Galata is neutral or Turkish-controlled.</p><p><b>Capture routes remain exclusive to Siege Preparation — Galata.</b> Successful capture alone opens Who Shall Govern Galata?; ordinary diplomacy never does.</p>`:''}</div>`;
    $('#open-galata-panel').onclick=()=>{galataPanelOpen=!galataPanelOpen;renderDiplomacy();};
    const update=(key,value)=>commit(()=>data.preparationPreview={...rehearsal(),[key]:value});
    if($('#galata-preview-state'))$('#galata-preview-state').onchange=e=>update('galataState',e.target.value);
    if($('#preview-siege'))$('#preview-siege').onchange=e=>update('siegeActive',e.target.checked);
    if($('#preview-delay'))$('#preview-delay').oninput=e=>{update('landDelayDays',Math.max(0,Math.min(99,Math.floor(Number(e.target.value)||0))));$('#preview-delay').focus();};
    if($('#inspect-galata-attack'))$('#inspect-galata-attack').onclick=()=>{selected='proposal:ottoman-attack-galata';collection='proposal';$('#collection').value=collection;categoryOptions();render();};
    $$('#diplomacy-view [data-political-action]').forEach(b=>b.onclick=()=>{$('#political-action-detail').textContent=p.actions.find(x=>x.id===b.dataset.politicalAction).description;});
  }

  function transform(){$('#world').setAttribute('transform',`translate(${pan.x},${pan.y}) scale(${zoom})`);$('#zoom-label').textContent=Math.round(zoom*100)+'%';}
  function comfortable(){zoom=.7;pan={x:20,y:70};transform();}
  function fit(){if(!drawn.length)return;const box=$('#graph').getBoundingClientRect();const ps=drawn.map(n=>positions[n.id]);const minX=Math.min(...ps.map(p=>p.x)),maxX=Math.max(...ps.map(p=>p.x+278)),minY=Math.min(...ps.map(p=>p.y)),maxY=Math.max(...ps.map(p=>p.y+118));zoom=Math.max(.06,Math.min(1.2,(box.width-70)/(maxX-minX),(box.height-210)/(maxY-minY)));pan={x:(box.width-(maxX-minX)*zoom)/2-minX*zoom,y:130-minY*zoom};transform();}
  function focusNode(){const p=positions[selected];if(!p){toast('Selected event is hidden by the current filters or scope.');return;}const box=$('#graph').getBoundingClientRect();zoom=Math.max(.65,Math.min(1.1,zoom));pan={x:box.width/2-(p.x+139)*zoom,y:box.height/2-(p.y+59)*zoom};transform();}
  function scale(factor,point){const box=$('#graph').getBoundingClientRect(),p=point||{x:box.width/2,y:box.height/2},next=Math.min(2.5,Math.max(.06,zoom*factor)),ratio=next/zoom;pan={x:p.x-(p.x-pan.x)*ratio,y:p.y-(p.y-pan.y)*ratio};zoom=next;transform();}
  function renderTable(){$('#table-view').innerHTML=`<h2 class="section-title">Event register</h2><p class="check-intro">${filtered.length} filtered records. Click a row to inspect choices and source evidence.</p><table><thead><tr><th>Stable ID / code</th><th>Event</th><th>Status</th><th>Choices</th><th>Timing / trigger</th></tr></thead><tbody>${filtered.map(n=>`<tr data-node="${esc(n.id)}" tabindex="0"><td><code>${esc(n.id)}</code></td><td>${esc(n.title)}${n.edited?' <span class="tag gold">edited</span>':''}</td><td>${esc(n.status)}</td><td>${n.choices.length}</td><td>${esc(n.timing|| (n.external?'External dispatch':n.entry?'Entry':'Unspecified'))}</td></tr>`).join('')}</tbody></table>`;}
  function renderChecks(){const types=[...new Set(analysis.findings.filter(f=>f.severity!=='info').map(f=>f.type))].sort();if(checkType&&!types.includes(checkType))checkType='';let findings=analysis.findings.filter(f=>f.severity!=='info'&&filtered.some(n=>n.id===f.node)&&(!checkType||f.type===checkType));const order={error:0,review:1,info:2};findings.sort((a,b)=>order[a.severity]-order[b.severity]);$('#checks-view').innerHTML=`<h2 class="section-title">Decisions worth your attention.</h2><p class="check-intro">Unscheduled content, broken links and explicit balance questions. Standalone random events are intentional and are not listed as problems.</p><div class="check-toolbar"><select id="check-type" aria-label="Check type"><option value="">All finding types</option>${types.map(t=>`<option ${t===checkType?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select><button id="export-report">Export check report</button></div><p class="muted small">${findings.length} findings shown · ${analysis.roots.length} declared entry / external trigger nodes · ${analysis.counts.errors} reference errors in collection</p>${findings.map(f=>`<button class="finding ${f.severity}" data-finding="${esc(f.node)}" ${f.edgeId?`data-finding-edge="${esc(f.edgeId)}"`:''}><span class="flag">${f.severity}</span><span><strong>${esc(node(f.node)?.title||f.node)}</strong><small>${esc(f.message)}</small></span></button>`).join('')||'<p class="muted">No findings match the current filters.</p>'}`;$('#check-type').onchange=e=>{checkType=e.target.value;renderChecks();};$('#export-report').onclick=()=>download({collection,generatedAt:new Date().toISOString(),counts:analysis.counts,findings:analysis.findings},'besieged-checks-'+collection+'.json');}
  function renderSources(){const q=sourceQuery.toLowerCase();$('#sources-view').innerHTML=`<h2 class="section-title">Evidence before interpretation.</h2><p class="check-intro">Six requested design sources are available as cached extracts. The fork sources are a pinned repository snapshot. No original synced file has been changed. Source excerpts and hashes travel with exported JSON.</p><p class="mono small muted">Fork commit ${esc(data.repositoryCommit||'unavailable')}</p><input id="source-search" type="search" placeholder="Search all source text, including Core mechanics…" aria-label="Search original source text" value="${esc(sourceQuery)}">${data.sources.filter(s=>!q||(s.name+' '+s.text).toLowerCase().includes(q)).map(s=>{const idx=s.text.toLowerCase().indexOf(q);const excerpt=q?s.text.slice(Math.max(0,idx-250),idx+1700):s.text;return`<article class="source-card"><h3>${esc(s.name)}</h3><span class="tag ${s.kind==='cached-extract'?'gold':'teal'}">${esc(s.kind)}</span><p class="locator">${esc(s.locator)}</p><div class="muted small">SHA-256 ${esc(s.sha256)}</div><details ${q?'open':''}><summary>${q?'Search excerpt':'Read source snapshot'}</summary><pre>${esc(excerpt)}</pre></details></article>`;}).join('')}`;$('#source-search').oninput=e=>{sourceQuery=e.target.value;const cursor=e.target.selectionStart;renderSources();$('#source-search').focus();$('#source-search').setSelectionRange(cursor,cursor);};}
  function effectHTML(e){let display=e.command;
    if(e.operation==='Change'&&e.variable){display=e.variable+' '+(/^[+-]?\d/.test(e.value)&&!e.value.startsWith('-')?'+':'')+e.value;}
    if(e.operation==='SetInt')display=e.variable+' = '+e.value;
    if(e.operation==='ChangeFraction')display=e.variable+' → '+e.value+' (fraction command)';
    if(e.operation==='RndChange')display=e.variable+' random delta '+e.value;
    if(e.operation==='set'||e.operation==='declare')display=e.variable+' = '+e.value+(e.operation==='declare'?' (initial value)':'');
    display=EventGraph.populationEffect(e)||display;
    const sign=/(?:^|\s)-\s*\d/.test(display)?'negative':/(?:\+\s*\d)/.test(display)?'positive':'neutral';
    return(e.guards.length?`<div class="branch-guard">WHEN ${esc(e.guards.join(' AND '))}</div>`:'')+`<span class="effect ${sign}" title="${esc('Exact source: <<'+e.command+'>> · line/paragraph '+e.line)}">${esc(display)}</span>`;
  }
  function routeHTML(e,incoming=false){const target=incoming?e.source:e.target;return`<button class="route" data-route="${esc(target)}" title="${esc(e.note)}">${incoming?'←':'→'} ${esc(nodeName(target))}<small>${esc(e.kind)}${e.conditions.length?' · '+esc(e.conditions.join(' AND ')):''}</small></button>`;}
  function reviewNavigation(n){const list=data.events.filter(e=>e.collection===collection),i=list.findIndex(e=>e.id===n.id);return `${i>0?`<button data-select="${esc(list[i-1].id)}">← Previous</button>`:''}<span>${i+1} / ${list.length}</span>${i<list.length-1?`<button data-select="${esc(list[i+1].id)}">Next →</button>`:''}`;}
  function renderInspector(){const n=node(selected);if(!n)return;const src=source(n),incoming=data.edges.filter(e=>e.target===n.id),outgoing=data.edges.filter(e=>e.source===n.id);const correlations=G.correlations(analysis.nodes,n.id);const checks=analysis.findings.filter(f=>f.node===n.id);const review=checks.filter(f=>f.severity!=='info');
    $('#inspector').innerHTML=`<div class="inspect-head"><div class="inspect-top"><span>${esc(n.code)}</span><button id="edit-event">Edit event</button></div><h2>${esc(n.title)}</h2><div class="tags"><span class="tag teal">${esc(n.origin)}</span><span class="tag">${esc(n.category)}</span><span class="tag">${esc(n.status)}</span>${n.edited?'<span class="tag gold">Edited locally</span>':''}${n.entry?'<span class="tag gold">Entry</span>':''}${''}</div><p class="source-ref mono">${esc(n.id)}</p><div class="review-navigation">${reviewNavigation(n)}</div><div class="inspect-buttons"><button id="add-link">+ Link</button><button id="show-downstream">View downstream</button></div></div>
    ${review.length?`<section class="inspect-section"><h3>Review flags · ${review.length}</h3>${review.slice(0,4).map(f=>`<div class="review-note">${esc(f.message)}</div>`).join('')}${review.length>4?`<button id="all-event-checks" class="text-button">View all ${review.length} findings</button>`:''}</section>`:''}
    <section class="inspect-section"><h3>Event & prerequisites</h3>${n.collection==='proposal'?`<p class="review-note">CURRENT UNITY FLOW. Map edits stay in this workbench. ${n.sourceEventId?`<button data-route="${esc(n.sourceEventId)}">Inspect original event →</button>`:'Scheduler slot, mapped from the implemented calendar.'}</p>`:''}<details open><summary>Read event narrative</summary><p class="narrative">${esc(n.description||'No separate narrative body supplied. Check the attached source excerpt.')}</p></details>${n.timing?`<span class="gate">Timing: ${esc(n.timing)}</span>`:''}${n.stage?`<span class="gate">Stage: ${esc(n.stage)}</span>`:''}${n.firing?`<span class="gate">Source firing field: ${esc(n.firing)} (semantics unverified)</span>`:''}${n.conditions.map(c=>`<span class="gate">${esc(c)}</span>`).join('')}${n.conditions.length?'':'<p class="small muted">No event-level prerequisite specified. Choice gates are shown below.</p>'}${n.effects.length?`<details><summary>Event-level commands / declarations (${n.effects.length})</summary>${n.effects.map(effectHTML).join('')}</details>`:''}</section>
    <section class="inspect-section"><h3>Choices & outcomes · ${n.choices.length}</h3>${n.collection==='proposal'?'<p class="small muted">Current choices and effects from Unity. Balance questions are marked above.</p>':''}${n.choices.map((c,i)=>`<article class="choice"><div class="choice-title"><span class="choice-number">${i+1}</span>${esc(c.label.replace(/#focus:\d+/g,''))}</div>${c.extraction==='prose-review'?'<span class="tag gold">Prose extraction · review</span>':''}${c.conditions.map(g=>`<span class="gate">REQUIRES ${esc(g)}</span>`).join('')}<div class="effects">${c.effects.map(effectHTML).join('')}</div>${!c.effects.length&&!c.outcomes.length&&n.collection!=='proposal'?'<p class="small muted">No numeric effect commands supplied.</p>':''}${c.outcomes.map(o=>`<div class="outcome"><b>${o.probability}%</b> ${esc(o.text)}</div>`).join('')}${c.text?n.collection==='proposal'&&c.extraction==='authored'?`<p class="proposal-outcome">${esc(c.text)}</p>`:`<details><summary>Outcome narrative / raw bonuses</summary><p>${esc(c.text)}</p></details>`:''}${outgoing.filter(e=>e.choiceId===c.id).map(e=>routeHTML(e)).join('')}</article>`).join('')||'<p class="muted">No choices extracted. Narrative-only and unfinished source events are preserved.</p>'}</section>
    <section class="inspect-section"><h3>Downstream & incoming links</h3>${outgoing.filter(e=>!e.choiceId).map(e=>routeHTML(e)).join('')}${incoming.map(e=>routeHTML(e,true)).join('')}${!outgoing.length&&!incoming.length?'<p>No explicit links. This may be an independently scheduled event.</p>':''}${[...incoming,...outgoing].length?'<button id="manage-links" class="text-button">Inspect / edit links…</button>':''}</section>
    <details class="inspect-section"><summary>Advanced: shared-state influences</summary><p class="small muted">Matching variable names, writer → condition reader. This does not prove causality, ordering or a reachable branch.</p>${n.writes.length?`<p class="mono small">Writes: ${esc(n.writes.join(', '))}</p>`:''}${n.reads.length?`<p class="mono small">Condition reads: ${esc(n.reads.join(', '))}</p>`:''}${correlations.slice(0,18).map(e=>`<button class="route" data-route="${esc(e.source===n.id?e.target:e.source)}">${e.source===n.id?'→':'←'} ${esc(nodeName(e.source===n.id?e.target:e.source))}<small>${esc(e.label)} · potential influence</small></button>`).join('')}${correlations.length>18?`<p class="small muted">${correlations.length-18} further variable matches. Enable Possible state links in the graph.</p>`:''}</details>
    <section class="inspect-section"><h3>Development notes</h3><p>${esc(n.notes||'No local notes yet. Use Edit event to add them.')}</p></section>
    <details class="inspect-section"><summary>Source evidence and exact commands</summary><p class="source-ref">${esc(src?.name||'Locally authored event')} · ${n.sourceLine?'line / paragraph / row '+n.sourceLine:'no imported locator'}</p>${src?`<p class="source-ref">${esc(src.locator)}</p>`:''}<details><summary>Read unmodified source excerpt</summary><pre>${esc(n.raw||'No imported source excerpt.')}</pre></details><p class="source-ref">Unity snapshot imported 21 October 2026. The preparation integration passed 52 checks; this map is a structural view, not a simulation.</p></details>`;
    $('#edit-event').onclick=()=>openEvent(n.id);$('#add-link').onclick=()=>openLink();$('#show-downstream').onclick=()=>{view='map';$('#scope').value='down';render();fit();};
    if($('#manage-links'))$('#manage-links').onclick=()=>openLinkList(n);if($('#all-event-checks'))$('#all-event-checks').onclick=()=>{view='checks';$('#search').value=n.id;render();};
    $$('#inspector .choice').forEach((element,i)=>{const button=document.createElement('button');button.className='text-button';button.textContent='Edit choice / bonuses';button.onclick=()=>openChoice(n.id,n.choices[i].id);element.appendChild(button);});
    const section=$$('#inspector .inspect-section').find(s=>s.querySelector('h3')?.textContent.startsWith('Choices & outcomes'));
    const add=document.createElement('button');add.textContent='+ Choice';add.onclick=()=>openChoice(n.id);section.appendChild(add);
  }
  function openModal(title,hint,fields){$('#editor-title').textContent=title;$('#editor-hint').textContent=hint;$('#editor-fields').innerHTML=fields;$('#editor-error').textContent='';$('#delete-record').hidden=false;$('#editor').showModal();}
  function label(text,id,value,tag='input',extra=''){return`<label class="editor-label" for="${id}">${text}</label><${tag} id="${id}" ${extra}${tag==='input'?` value="${esc(value)}">`:`>${esc(value)}</${tag}>`}`;}
  function openEvent(id,isNew=false){const n=node(id);editorMode='event';editorId=id;editNew=isNew;
    const structured=Object.fromEntries(['choices','effects','conditions','reads','writes','review'].map(k=>[k,n[k]]));
    openModal(isNew?'Create authored event':'Edit '+n.code,'Stable IDs and source excerpts are preserved. Edit choices, outcome commands and gates in the structured JSON. Changes stay in this map; Yarn is not rewritten.',
      `<p class="mono small">Stable ID: ${esc(n.id)}</p><div class="form-grid"><div>${label('Title','ed-title',n.title)}</div><div>${label('Code (labels may change; ID stays fixed)','ed-code',n.code)}</div></div><div class="form-grid"><div>${label('Category','ed-category',n.category)}</div><div>${label('Writing / implementation status','ed-status',n.status)}</div></div>${label('Narrative description','ed-description',n.description,'textarea','rows="3"')}${label('Timing / scheduler notes','ed-timing',n.timing||'')}${label('Development notes','ed-notes',n.notes,'textarea','rows="2"')}<label class="checkbox-label"><input id="ed-entry" type="checkbox" ${n.entry?'checked':''}> Entry node</label><label class="checkbox-label"><input id="ed-external" type="checkbox" ${n.external?'checked':''}> External / scheduler trigger</label>${label('Choices, effects and prerequisites (JSON)','ed-json',JSON.stringify(structured,null,2),'textarea','class="json-editor" spellcheck="false"')}`);
  }
  function newEvent(){const id='authored:'+crypto.randomUUID(),n={id,code:'new_event',title:'New event',collection,category:collection==='catalogue'?'catalogue':'story',origin:'authored',status:'Draft',description:'',notes:'',raw:'',choices:[],effects:[],conditions:[],reads:[],writes:[],review:[],entry:false,external:false};
    // The temporary node is removed if this dialog is cancelled.
    data.events.push(n);openEvent(id,true);$('#delete-record').hidden=true;
  }
  function effectRow(e={operation:'Change',variable:'',value:'0',guards:[],command:'',line:0}){
    return `<div class="edit-effect-row" data-original-command="${esc(e.command)}" data-line="${e.line||0}"><div class="effect-form-grid"><label>Operation<select class="ef-operation">${['Change','SetInt','ChangeFraction','RndChange','set','declare','command'].map(op=>`<option ${op===e.operation?'selected':''}>${op}</option>`).join('')}</select></label><label>Variable<input class="ef-variable" value="${esc(e.variable)}" placeholder="iMoney or money"></label><label>Value / expression<input class="ef-value" value="${esc(e.value)}" placeholder="-5000"></label><button type="button" class="remove-effect danger" aria-label="Remove effect">×</button></div><label class="editor-label">Branch guards (one per line)<textarea class="ef-guards" rows="1">${esc(e.guards.join('\n'))}</textarea></label></div>`;
  }
  function outcomeRow(o={probability:50,text:''}){return`<div class="edit-outcome-row"><label>Chance %<input class="oc-prob" type="number" min="0" max="100" step="0.01" value="${o.probability}"></label><label>Outcome and bonuses<textarea class="oc-text" rows="2">${esc(o.text)}</textarea></label><button type="button" class="remove-outcome danger" aria-label="Remove probability outcome">×</button></div>`;}
  function bindChoiceRows(){for(const b of $$('#effect-rows .remove-effect'))b.onclick=()=>b.closest('.edit-effect-row').remove();for(const b of $$('#outcome-rows .remove-outcome'))b.onclick=()=>b.closest('.edit-outcome-row').remove();}
  function openChoice(eventId,choiceId=''){
    editorMode='choice';editorId=eventId;editorChoice=choiceId;editNew=false;const n=node(eventId),c=n.choices.find(c=>c.id===choiceId)||{label:'',text:'',conditions:[],effects:[],outcomes:[]};
    openModal(choiceId?'Edit choice and bonuses':'Add choice','Change is a delta; SetInt is an absolute assignment. Fraction values retain the source scale (for example 0.15). Branch guards distinguish random outcomes. Source text remains available after edits.',
      label('Choice label','ch-label',c.label,'textarea','rows="2"')+label('Choice prerequisites (one per line)','ch-conditions',c.conditions.join('\n'),'textarea','rows="2"')+label('Outcome narrative / prose bonuses','ch-text',c.text,'textarea','rows="3"')+'<h3>Numeric / state effects</h3><div id="effect-rows">'+c.effects.map(effectRow).join('')+'</div><button type="button" id="add-effect">+ Effect</button><h3>Probability outcomes</h3><div id="outcome-rows">'+c.outcomes.map(outcomeRow).join('')+'</div><button type="button" id="add-outcome">+ Probability outcome</button>');
    $('#delete-record').hidden=!choiceId;$('#add-effect').onclick=()=>{$('#effect-rows').insertAdjacentHTML('beforeend',effectRow());bindChoiceRows();};$('#add-outcome').onclick=()=>{$('#outcome-rows').insertAdjacentHTML('beforeend',outcomeRow());bindChoiceRows();};bindChoiceRows();
  }
  function targetOptions(current){return`<option value="">Select a target…</option>`+data.events.filter(n=>n.collection===collection).map(n=>`<option value="${esc(n.id)}" ${n.id===current?'selected':''}>${esc(n.code+' · '+n.title)}</option>`).join('');}
  function openLink(id=''){const existing=data.edges.find(e=>e.id===id);editorMode='link';editorId=id;editNew=false;const n=node(existing?.source||selected);const e=existing||{source:selected,target:'',kind:'manual',label:'',choiceId:'',conditions:[],note:''};
    openModal(existing?'Inspect / edit link':'Add directed link','Imported links retain their evidence when edited. Manual links represent your design decisions. A missing target is allowed so unfinished branches remain visible.',
      `<p>From <strong>${esc(n?.title||e.source)}</strong> <code>${esc(e.source)}</code></p>${label('Target stable ID (select below or type a missing target)','ed-target',e.target)}<select id="ed-target-picker" aria-label="Pick target event">${targetOptions(e.target)}</select>${label('Link label','ed-label',e.label)}<label class="editor-label" for="ed-kind">Relationship type</label><select id="ed-kind">${['manual','jump','schedule'].map(k=>`<option ${k===e.kind?'selected':''}>${k}</option>`).join('')}</select><label class="editor-label" for="ed-choice">Source choice</label><select id="ed-choice"><option value="">Event-level / shared continuation</option>${(n?.choices||[]).map(c=>`<option value="${esc(c.id)}" ${c.id===e.choiceId?'selected':''}>${esc(c.label.slice(0,100))}</option>`).join('')}</select>${label('Conditions (one per line)','ed-conditions',e.conditions.join('\n'),'textarea','rows="3"')}${label('Notes / source interpretation','ed-link-notes',e.note,'textarea','rows="2"')}`);
    $('#ed-target-picker').onchange=e=>$('#ed-target').value=e.target.value;$('#delete-record').hidden=!existing;
  }
  function openLinkList(n){editorMode='list';editNew=false;const links=data.edges.filter(e=>e.source===n.id||e.target===n.id);openModal('Links for '+n.code,'Select a link to inspect its target, conditions and source attribution.',links.map(e=>`<button type="button" class="route" data-edit-link="${esc(e.id)}">${esc(e.source)} → ${esc(e.target)}<small>${esc(e.kind+' · '+e.label)}</small></button>`).join(''));$('#delete-record').hidden=true;$('#editor-form button[type=submit]').hidden=true;}
  function closeEditor(){if(editNew){data.events=data.events.filter(n=>n.id!==editorId);editNew=false;}$('#editor-form button[type=submit]').hidden=false;$('#editor').close();}
  $('#editor-form').onsubmit=e=>{e.preventDefault();try{
    if(editorMode==='choice'){
      const n=node(editorId),prior=n.choices.find(c=>c.id===editorChoice),label=$('#ch-label').value.trim();if(!label)throw new Error('A choice label is required.');
      const effects=$$('#effect-rows .edit-effect-row').map(row=>{const operation=row.querySelector('.ef-operation').value,variable=row.querySelector('.ef-variable').value.trim(),value=row.querySelector('.ef-value').value.trim(),guards=row.querySelector('.ef-guards').value.split('\n').map(s=>s.trim()).filter(Boolean);if(operation!=='command'&&!variable)throw new Error('Each effect needs a variable name.');return{operation,variable,value,guards,line:Number(row.dataset.line),command:operation==='command'?row.dataset.originalCommand:operation==='set'||operation==='declare'?`${operation} $${variable} = ${value}`:`${operation} ${variable} ${value}`};});
      const outcomes=$$('#outcome-rows .edit-outcome-row').map(row=>({probability:Number(row.querySelector('.oc-prob').value),text:row.querySelector('.oc-text').value}));
      const c={...(prior||{}),id:prior?.id||n.id+':choice:'+crypto.randomUUID(),label,text:$('#ch-text').value,conditions:$('#ch-conditions').value.split('\n').map(s=>s.trim()).filter(Boolean),effects,outcomes,extraction:prior?.extraction||'authored',edited:true};
      const updated=G.refreshDerived({...n,choices:prior?n.choices.map(x=>x.id===prior.id?c:x):[...n.choices,c],edited:true});const candidate=clone(data);candidate.events=candidate.events.map(x=>x.id===n.id?updated:x);const errors=G.validate(candidate);if(errors.length)throw new Error(errors.join('\n'));commit(()=>data=candidate);
    }else if(editorMode==='event'){
      const n=node(editorId),structured=JSON.parse($('#ed-json').value);const allowed=['choices','effects','conditions','reads','writes','review'];if(Object.keys(structured).some(k=>!allowed.includes(k)))throw new Error('Only choices, effects, conditions, reads, writes and review are allowed in this JSON panel.');
      const updated={...n,...structured,title:$('#ed-title').value.trim(),code:$('#ed-code').value.trim(),category:$('#ed-category').value.trim(),status:$('#ed-status').value.trim(),description:$('#ed-description').value,notes:$('#ed-notes').value,timing:$('#ed-timing').value,entry:$('#ed-entry').checked,external:$('#ed-external').checked,edited:true};
      if(!updated.title||!updated.code)throw new Error('Title and code are required.');
      const candidate=clone(data);candidate.events=candidate.events.map(x=>x.id===n.id?updated:x);const errors=G.validate(candidate);if(errors.length)throw new Error(errors.join('\n'));G.refreshDerived(updated);
      if(editNew){data.events=data.events.filter(x=>x.id!==n.id);editNew=false;commit(()=>data.events.push(updated));selected=updated.id;}else commit(()=>data.events=data.events.map(x=>x.id===n.id?updated:x));
    }else if(editorMode==='link'){
      const prior=data.edges.find(e=>e.id===editorId),target=$('#ed-target').value.trim();if(!target)throw new Error('Target stable ID is required.');const updated={...(prior||{}),id:prior?.id||'manual:'+crypto.randomUUID(),source:prior?.source||selected,target,kind:$('#ed-kind').value,label:$('#ed-label').value,choiceId:$('#ed-choice').value,conditions:$('#ed-conditions').value.split('\n').map(s=>s.trim()).filter(Boolean),note:$('#ed-link-notes').value,origin:prior?.origin||'authored',edited:true};const candidate=clone(data);candidate.edges=prior?candidate.edges.map(e=>e.id===prior.id?updated:e):[...candidate.edges,updated];const errors=G.validate(candidate);if(errors.length)throw new Error(errors.join('\n'));commit(()=>data=candidate);
    }
    closeEditor();render();toast('Changes saved locally. Export JSON to keep a project copy.');
  }catch(error){$('#editor-error').textContent=error.message;}};
  $('#delete-record').onclick=()=>{if(editorMode==='choice'){if(!confirm('Delete this choice and links attached to it? Undo is available.'))return;commit(()=>{const n=node(editorId);n.choices=n.choices.filter(c=>c.id!==editorChoice);data.edges=data.edges.filter(e=>e.choiceId!==editorChoice);n.edited=true;G.refreshDerived(n);});}else if(editorMode==='event'){if(!confirm('Delete this event and its incoming/outgoing links from the local map? Undo is available.'))return;const id=editorId;commit(()=>{data.events=data.events.filter(n=>n.id!==id);data.edges=data.edges.filter(e=>e.source!==id&&e.target!==id);});}else if(editorMode==='link'){if(!confirm('Delete this directed link from the local map?'))return;commit(()=>data.edges=data.edges.filter(e=>e.id!==editorId));}closeEditor();render();};
  function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  $('#export-btn').onclick=()=>{download({...data,exportedAt:new Date().toISOString()},'besieged-events-'+new Date().toISOString().slice(0,10)+'.json');toast('JSON export downloaded. Keep it with your game project.');};
  $('#import-btn').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024)throw new Error('Import is limited to 30 MB.');const candidate=JSON.parse(await file.text()),errors=G.validate(candidate);if(errors.length)throw new Error(errors.slice(0,10).join('\n'));if(!confirm('Replace this local workspace with '+candidate.events.length+' events from '+file.name+'? Export first if needed. Undo can recover the current workspace.'))return;commit(()=>data=candidate);categoryOptions();render();fit();toast('Validated JSON imported.');}catch(err){alert('Import rejected: '+err.message);}finally{e.target.value='';}};
  $('#reset-data').onclick=()=>{if(!confirm('Reset to the bundled source snapshot? Export any work you want to keep first. Undo is available.'))return;commit(()=>data=clone(original));categoryOptions();$('#help').close();render();fit();};
  $('#help-btn').onclick=()=>$('#help').showModal();$('#close-help').onclick=()=>$('#help').close();$('#close-editor').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});
  $('#undo').onclick=undo;$('#redo').onclick=redo;$('#new-event').onclick=newEvent;
  $('#collection').onchange=e=>{collection=e.target.value;selected='';view='map';$('#search').value='';$('#category').value='';$('#status').value='';$('#health-filter').value='';$('#scope').value='all';categoryOptions();render();fit();};
  for(const id of ['category','status','origin','health-filter'])$('#'+id).onchange=()=>{render();fit();};$('#search').oninput=()=>{render();fit();};
  $('#clear-filters').onclick=()=>{for(const id of ['search','category','status','origin','health-filter'])$('#'+id).value='';$('#scope').value='all';render();fit();};
  for(const id of ['show-jumps','show-schedule','show-state','show-potential','scope','flow-section'])$('#'+id).onchange=()=>{if(id==='flow-section'){const section=$('#flow-section').value;selected=data.events.find(n=>n.collection===collection&&(section==='preparation'?n.section==='calendar':n.section===section))?.id||selected;$('#scope').value='all';$('#category').value='';$('#search').value='';}render();comfortable();};
  $('#fit').onclick=fit;$('#focus-node').onclick=focusNode;$('#zoom-in').onclick=()=>scale(1.2);$('#zoom-out').onclick=()=>scale(1/1.2);
  $('#layout').onclick=()=>{commit(()=>data.events.filter(n=>n.collection===collection).forEach(n=>{const bundled=original.events.find(e=>e.id===n.id);if(bundled?.position)n.position=clone(bundled.position);else delete n.position;delete n.userPosition;}));fit();toast('Automatic layout restored. Undo restores your positions.');};
  document.addEventListener('click',e=>{const s=e.target.closest('[data-select]'),v=e.target.closest('[data-view]'),r=e.target.closest('[data-route]'),t=e.target.closest('#table-view [data-node]'),f=e.target.closest('[data-finding]'),link=e.target.closest('[data-edit-link]');if(s)select(s.dataset.select);if(v){view=v.dataset.view;if(view==='plan'){collection='proposal';$('#collection').value=collection;categoryOptions();}render();if(view==='map')comfortable();}if(r)select(r.dataset.route,true);if(t)select(t.dataset.node);if(f){select(f.dataset.finding);if(f.dataset.findingEdge)openLink(f.dataset.findingEdge);}if(link){$('#editor').close();$('#editor-form button[type=submit]').hidden=false;openLink(link.dataset.editLink);}});
  const svg=$('#graph');svg.addEventListener('wheel',e=>{e.preventDefault();const b=svg.getBoundingClientRect();scale(Math.exp(-e.deltaY*.0015),{x:e.clientX-b.left,y:e.clientY-b.top});},{passive:false});
  svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;const n=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(edge){const record=drawnEdges.find(x=>x.id===edge.dataset.edge);if(record?.kind==='state')toast(record.note+' Variable: '+record.label);else if(record)openLink(record.id);return;}const id=n?.dataset.node;if(id&&!node(id)){toast('Diagnostic card: no source event exists for '+id);return;}drag={id,start:{x:e.clientX,y:e.clientY},pan:{...pan},position:id?{...positions[id]}:null,moved:false};svg.setPointerCapture(e.pointerId);});
  svg.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.start.x,dy=e.clientY-drag.start.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;if(!drag.moved)return;if(drag.id){const p={x:drag.position.x+dx/zoom,y:drag.position.y+dy/zoom};positions[drag.id]=p;const element=[...$('#world').querySelectorAll('[data-node]')].find(el=>el.dataset.node===drag.id);element?.setAttribute('transform',`translate(${p.x},${p.y})`);}else{pan={x:drag.pan.x+dx,y:drag.pan.y+dy};transform();}});
  function endDrag(){if(!drag)return;const d=drag;drag=null;if(d.id&&d.moved){const p=positions[d.id];commit(()=>{node(d.id).position=p;if(collection==='proposal'&&$('#scope').value==='near')node(d.id).userPosition=p;});}else if(d.id)select(d.id);}
  svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointercancel',endDrag);
  document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#editor').open||$('#help').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.key==='Enter'||e.key===' '){const n=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(n){e.preventDefault();select(n.dataset.node);}if(edge){e.preventDefault();const x=drawnEdges.find(l=>l.id===edge.dataset.edge);x?.kind==='state'?toast(x.note):openLink(edge.dataset.edge);}}if(e.key==='f')fit();});
  $('#toggle-archive').onclick=()=>{const group=$('#archive-collections');group.hidden=!group.hidden;$('#toggle-archive').textContent=group.hidden?'Show reference archive':'Hide reference archive';};
  $('#collection').value=collection;categoryOptions();render();requestAnimationFrame(()=>{if(view==='map')comfortable();if(persistenceError)toast(persistenceError);else if(stored)$('#save-state').textContent='Restored browser workspace';});
})();

